import{z as A,x as o,o as P,c as p,q as s,j as l,D as e,d as t,s as i,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"MPLS","description":"","frontmatter":{"title":"MPLS","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mpls.md","filePath":"cs/mpls.md","lastUpdated":1791063341000}'),B={name:"cs/mpls.md"};function d(m,a,S,L,C,I){const r=o("Mermaid");return P(),p("div",null,[a[2]||(a[2]=s('<h1 id="mpls" tabindex="-1">MPLS <a class="header-anchor" href="#mpls" aria-label="Permalink to &quot;MPLS&quot;">​</a></h1><div class="epigraph"><p>入口把前缀或流量类映射成标签，中间只交换标签；把 TE 与 VPN 从「每跳最长前缀」里解放出来。</p><footer>—— 据 RFC 3031 MPLS 架构；RFC 5036 LDP；RFC 3209 RSVP-TE 整理</footer></div><p><a href="/cs/traffic-engineering">上一课</a> 要显式路径。缺口是<strong>数据面怎么走显式路径而不改 IP 头</strong>：MPLS 标签栈、LDP 与 RSVP-TE。本课不把段路由 SID 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>IP 每跳 LPM，路径随 IGP 变。MPLS：ingress 压入标签，transit 查 ILM 换标签，egress 弹出。PHP 可在倒数第二跳弹出。TE LSP 用 RSVP 预留带宽；LDP 跟 IGP 拓扑走，不单独 TE。VPN（后课对照 EVPN）用两层标签：外层走隧道，内层选 VRF。</p><p><span class="marginnote">LPM（最长前缀匹配）就是每一跳都拿目的 IP 与路由表里所有前缀比对，选掩码最长的那条。它是 IP 转发的本职，但也意味着路径由每跳各自的路由表决定；MPLS 入口一次定夺、中间照标签走，显式路径才有了着落。</span></p><p>不要把标签当成 MAC：标签是本跳局部的，MAC 是接口烧录或学习来的。</p><p><span class="marginnote">RFC 3031。标签 20 比特。流量工程与 VPN 是 MPLS 的两大理由，不是「比 IP 更快的查找」神话——TCAM 后课会说 IP 也能线速。</span></p><h3 id="标签是局部-fec" tabindex="-1">标签是局部 FEC <a class="header-anchor" href="#标签是局部-fec" aria-label="Permalink to &quot;标签是局部 FEC&quot;">​</a></h3><p>中间不查用户 IP。LDP 跟随 IGP，RSVP-TE 带带宽。VPN 常用两层标签。更快查找不是引入 MPLS 的理由。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画：IP 包 → 压标签 → 交换 → 弹标签 → IP。对照 VLAN：VLAN 是广播域着色，MPLS 是转发等价类。与 GRE 后课对照：GRE 是 IP-in-IP 风格隧道，中间仍 LPM。</p>',12)),(P(),l(n,null,{default:e(()=>[i(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ING%5B%22%E5%85%A5%E5%8F%A3%E5%8E%8B%E5%85%A5%22%5D%20--%3E%20SW%5B%22%E4%B8%AD%E9%97%B4%E4%BA%A4%E6%8D%A2%E6%A0%87%E7%AD%BE%22%5D%0A%20%20SW%20--%3E%20EGR%5B%22%E5%87%BA%E5%8F%A3%E5%BC%B9%E5%87%BA%22%5D%0A%20%20FEC%5B%22%E8%BD%AC%E5%8F%91%E7%AD%89%E4%BB%B7%E7%B1%BB%22%5D%20--%3E%20ING%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"BGP 下一跳可达可变成「到下一跳的 LSP」，加速收敛（PIC）是工程。IXP 上通常仍是 IP 对等，MPLS 多在 AS 内。PFC 可在 MPLS 以太网上按 TC 映射，与有线课衔接。",-1)),a[5]||(a[5]=E("p",null,"失败：LSP 断了要 make-before-break 或 IGP 绕路，否则黑洞，像 RR 藏备选。",-1)),(P(),l(n,null,{default:e(()=>[i(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20PKT%5B%22IP%20%E5%8C%85%3A%20%E7%9B%AE%E7%9A%84%2010.1.1.0%2F24%22%5D%20--%3E%20ING%5B%22%E5%85%A5%E5%8F%A3%20LER%3A%20%E6%9F%A5%20FEC%20%E5%8E%8B%E5%85%A5%E6%A0%87%E7%AD%BE%20100%22%5D%0A%20%20ING%20--%3E%20T1%5B%22%E4%B8%AD%E9%97%B4%20LSR%3A%20ILM%20%E6%8A%8A%20100%20%E6%8D%A2%E6%88%90%20200%22%5D%0A%20%20T1%20--%3E%20PEN%5B%22%E5%80%92%E6%95%B0%E7%AC%AC%E4%BA%8C%E8%B7%B3%3A%20PHP%20%E6%8F%90%E5%89%8D%E5%BC%B9%E5%87%BA%E6%A0%87%E7%AD%BE%22%5D%0A%20%20PEN%20--%3E%20EGR%5B%22%E5%87%BA%E5%8F%A3%20LER%3A%20%E6%94%B6%E5%88%B0%E8%A3%B8%20IP%2C%20%E6%AD%A3%E5%B8%B8%E8%BD%AC%E5%8F%91%22%5D%0A%20%20T1%20--%3E%20NOTE%5B%22%E5%85%A8%E7%A8%8B%E6%9C%AA%E5%AF%B9%E8%AF%A5%20IP%20%E5%81%9A%E6%9C%80%E9%95%BF%E5%89%8D%E7%BC%80%E5%8C%B9%E9%85%8D%22%5D%0A%20%20NOTE%20--%3E%20EGR%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">PHP（penultimate hop popping，倒数第二跳弹出）就是让弹出标签的活儿由倒数第二个路由器提前干，出口路由器收到时已经是干净 IP 包。省的是出口那一跳「弹完再查」的双重查表——一两微秒在核心网里也是钱。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 GMPLS 光层。分段路由是下一课。后课默认：MPLS 用标签换路径与 VPN 上下文；中间不查 IP。</p><p>「MPLS 已死」口号忽略大量运营商 VPN；SR 是演化不是瞬间替换。</p><p><span class="marginnote">可以把标签想象成行李托运条：入口柜台贴上「中转北京→伦敦」，中间每一站只扫条换条，不需要拆开行李看你到底要去哪条街（目的 IP）。标签本站生效、用完即换，MAC 地址则是网卡出厂就带着的身份证，两者完全不是一类东西。</span></p><p>下一课<a href="/cs/segment-routing">分段路由</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>标签转发实现 FEC 与显式路径。</li><li>LDP 跟随 IGP；RSVP-TE 做带宽 LSP。</li><li>中间跳不必 LPM 该用户 IP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 3031；RFC 3209；RFC 5036。</li></ul>',8))])}const c=A(B,[["render",d]]);export{h as __pageData,c as default};
